export interface TextAroundSlot {
  after: string;
  before: string;
  hasSlot: boolean;
}

export const splitTextAroundSlot = (
  text: string,
  slot: string,
): TextAroundSlot => {
  const slotIndex = text.indexOf(slot);

  if (slotIndex === -1) {
    return {after: '', before: text, hasSlot: false};
  }

  return {
    after: text.slice(slotIndex + slot.length),
    before: text.slice(0, slotIndex),
    hasSlot: true,
  };
};

