const ts = require('typescript');
const path = require('path');
const configPath = ts.findConfigFile('./', ts.sys.fileExists, 'tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, path.dirname(configPath));
const program = ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
const files = [
  'src/assets/svg/index.ts',
  'src/assets/svg/arrow-right-outline.tsx',
  'src/assets/svg/badge-dot.tsx',
  'src/assets/svg/caret-down-fill.tsx',
  'src/assets/svg/clock-fill.tsx',
  'src/assets/svg/dashed-divider.tsx',
  'src/assets/svg/doctor-avatar-status.tsx',
  'src/assets/svg/map-pin-fill.tsx',
  'src/assets/svg/queue-fill.tsx',
  'src/assets/svg/video-cam-fill.tsx',
  'src/assets/svg/warning-fill.tsx',
  'src/i18n/locale/en.ts',
  'src/i18n/locale/zh.ts',
  'src/i18n/locale/zh_tw.ts',
  'src/screens/appointments-screen/appointments-screen.styles.ts',
  'src/screens/consult-screen/consult-doctor-list.tsx',
  'src/screens/consult-screen/consult-plan-chips.tsx',
  'src/screens/consult-screen/consult-screen.styles.ts',
  'src/screens/consult-screen/consult-screen.tsx',
  'src/screens/consult-screen/consult-service-selection.ts',
  'src/screens/consult-screen/unpurchased-gp-doctor-list.ts',
  'src/screens/doctor-detail-screen/consult-pass-product.ts',
  'src/screens/doctor-detail-screen/doctor-booking-flow.ts',
  'src/screens/doctor-detail-screen/doctor-detail-screen.styles.ts',
  'src/screens/doctor-detail-screen/doctor-detail-screen.tsx',
  'src/screens/doctor-detail-screen/recommended-gp.ts',
  'src/screens/my-appointment-screen/my-appointment-screen.styles.ts',
  'src/screens/my-appointment-screen/my-appointment-screen.tsx',
];
const byPath = new Map(program.getSourceFiles().map(sf => [path.relative(process.cwd(), sf.fileName), sf]));
let semantic = 0;
let suggestion = 0;
for (const file of files) {
  const sf = byPath.get(file);
  if (!sf) {
    console.log('MISSING', file);
    continue;
  }
  const diags = [
    ...program.getSemanticDiagnostics(sf),
    ...program.getSyntacticDiagnostics(sf),
    ...program.getSuggestionDiagnostics(sf),
  ];
  for (const d of diags) {
    const kind = d.reportsUnnecessary || d.reportsDeprecated ? 'suggestion' : 'semantic';
    if (kind === 'suggestion') suggestion++; else semantic++;
    const start = d.start ?? 0;
    const pos = sf.getLineAndCharacterOfPosition(start);
    console.log(`${kind} ${file}:${pos.line + 1}:${pos.character + 1} TS${d.code} ${ts.flattenDiagnosticMessageText(d.messageText, ' ')}`);
  }
}
console.log('semantic', semantic, 'suggestion', suggestion, 'programOptions.module', parsed.options.module, 'errors', parsed.errors.length);
if (parsed.errors.length) {
  for (const e of parsed.errors) console.log('config', ts.flattenDiagnosticMessageText(e.messageText, ' '));
}
JS
